export interface ConnectorConfig {
  pipedriveApiToken: string
  fetch?: typeof fetch
  maxRetries?: number
  baseRetryDelayMs?: number
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      number?: number
      field: {
        id: string
        type: string
        ref?: string
      }
    }>
  }
}

export interface ConnectorResult {
  personId: number
  organizationId: number
  dealId: number
}

interface PipedrivePersonResponse {
  data: { id: number }
}

interface PipedriveOrganizationResponse {
  data: { id: number }
}

interface PipedriveDealResponse {
  data: { id: number }
}

const FIELD_IDS = {
  firstName: 'JwWggjAKtOkA',
  lastName: 'last_name_field_id',
  email: 'SMEUb7VJz92Q',
  company: 'company_field_id',
  organization: 'organization_field_id',
  phone: 'phone_field_id',
  dealName: 'dealname_field_id',
  price: 'price_field_id',
} as const

function extractAnswer(payload: TypeformWebhookPayload, fieldId: string): string | number | undefined {
  const answer = payload.form_response.answers.find((a) => a.field.id === fieldId)
  if (!answer) return undefined
  if (answer.type === 'email') return answer.email
  if (answer.type === 'number') return answer.number
  return answer.text
}

function getRequiredString(payload: TypeformWebhookPayload, fieldId: string, fieldName: string): string {
  const value = extractAnswer(payload, fieldId)
  if (value === undefined || value === '') {
    throw new Error(`Missing required field: ${fieldName}`)
  }
  return String(value)
}

function getOptionalString(payload: TypeformWebhookPayload, fieldId: string): string | undefined {
  const value = extractAnswer(payload, fieldId)
  if (value === undefined || value === '') return undefined
  return String(value)
}

function getOptionalNumber(payload: TypeformWebhookPayload, fieldId: string): number | undefined {
  const value = extractAnswer(payload, fieldId)
  if (value === undefined) return undefined
  const num = typeof value === 'number' ? value : Number(value)
  return Number.isNaN(num) ? undefined : num
}

async function fetchWithRetry(
  url: string,
  options: RequestInit,
  config: ConnectorConfig,
  attempt = 0,
): Promise<Response> {
  const fetchFn = config.fetch ?? fetch
  const maxRetries = config.maxRetries ?? 3
  const baseDelay = config.baseRetryDelayMs ?? 1000

  const response = await fetchFn(url, options)

  if (response.status === 429 || (response.status >= 500 && response.status < 600)) {
    if (attempt < maxRetries) {
      const retryAfter = response.headers.get('retry-after')
      let delayMs: number
      if (retryAfter) {
        const asSeconds = Number(retryAfter)
        if (!Number.isNaN(asSeconds)) {
          delayMs = asSeconds * 1000
        } else {
          const date = new Date(retryAfter)
          delayMs = date.getTime() - Date.now()
          if (Number.isNaN(delayMs) || delayMs < 0) delayMs = baseDelay * 2 ** attempt
        }
      } else {
        delayMs = baseDelay * 2 ** attempt
      }
      if (delayMs > 0 && !Number.isNaN(delayMs)) {
        await new Promise((resolve) => setTimeout(resolve, delayMs))
      }
      return fetchWithRetry(url, options, config, attempt + 1)
    }
  }

  return response
}

async function createPerson(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<number> {
  const firstName = getRequiredString(payload, FIELD_IDS.firstName, 'first_name')
  const lastName = getRequiredString(payload, FIELD_IDS.lastName, 'last_name')
  const email = getRequiredString(payload, FIELD_IDS.email, 'email')
  const phone = getOptionalString(payload, FIELD_IDS.phone)

  const body = {
    name: `${firstName} ${lastName}`,
    email,
    ...(phone ? { phone } : {}),
  }

  const response = await fetchWithRetry(
    'https://api.pipedrive.com/v2/persons',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.pipedriveApiToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    },
    config,
  )

  if (!response.ok) {
    throw new Error(`Pipedrive create person failed: ${response.status} ${response.statusText} at POST https://api.pipedrive.com/v2/persons`)
  }

  const data = (await response.json()) as PipedrivePersonResponse
  return data.data.id
}

async function createOrganization(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<number> {
  const company = getOptionalString(payload, FIELD_IDS.company)
  const organization = getOptionalString(payload, FIELD_IDS.organization)
  const orgName = company ?? organization

  if (!orgName) {
    throw new Error('Missing required field: company or organization for organization name')
  }

  const body = { name: orgName }

  const response = await fetchWithRetry(
    'https://api.pipedrive.com/v2/organizations',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.pipedriveApiToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    },
    config,
  )

  if (!response.ok) {
    throw new Error(`Pipedrive create organization failed: ${response.status} ${response.statusText} at POST https://api.pipedrive.com/v2/organizations`)
  }

  const data = (await response.json()) as PipedriveOrganizationResponse
  return data.data.id
}

async function createDeal(
  payload: TypeformWebhookPayload,
  personId: number,
  organizationId: number,
  config: ConnectorConfig,
): Promise<number> {
  const title = getOptionalString(payload, FIELD_IDS.dealName)
  const value = getOptionalNumber(payload, FIELD_IDS.price)

  const body: Record<string, unknown> = {
    person_id: personId,
    org_id: organizationId,
  }
  if (title) body.title = title
  if (value !== undefined) body.value = value

  const response = await fetchWithRetry(
    'https://api.pipedrive.com/v2/deals',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.pipedriveApiToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    },
    config,
  )

  if (!response.ok) {
    throw new Error(`Pipedrive create deal failed: ${response.status} ${response.statusText} at POST https://api.pipedrive.com/v2/deals`)
  }

  const data = (await response.json()) as PipedriveDealResponse
  return data.data.id
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<ConnectorResult> {
  if (!config.pipedriveApiToken) {
    throw new Error('Missing required config: pipedriveApiToken')
  }

  if (payload.event_type !== 'form_response') {
    throw new Error(`Unsupported event type: ${payload.event_type}`)
  }

  const personId = await createPerson(payload, config)
  const organizationId = await createOrganization(payload, config)
  const dealId = await createDeal(payload, personId, organizationId, config)

  return { personId, organizationId, dealId }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, TARGET_ENDPOINTS, contractFetch, fakeFetch, jsonResponse, RecordedCall } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.personId).toBe(12345)
    expect(result.organizationId).toBe(67890)
    expect(result.dealId).toBe(54321)
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons' && req.method === 'POST') {
        return jsonResponse({ data: { id: 12345 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/organizations' && req.method === 'POST') {
        return jsonResponse({ data: { id: 67890 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals' && req.method === 'POST') {
        return jsonResponse({ data: { id: 54321 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = fake.fetch
    calls = fake.calls
    baseConfig = { pipedriveApiToken: 'test-token', fetch }
  })

  it('creates person, organization, and deal with correct field mapping', async () => {
    const payload = SOURCE_EXAMPLE as unknown as TypeformWebhookPayload
    const result = await handle(payload, baseConfig)

    expect(result).toEqual({ personId: 12345, organizationId: 67890, dealId: 54321 })
    expect(calls).toHaveLength(3)

    // Person creation
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.pipedrive.com/v2/persons')
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-token')
    expect(calls[0].json).toEqual({
      name: 'Laura Smith',
      email: 'laura@example.com',
      phone: '123-456-7890',
    })

    // Organization creation
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://api.pipedrive.com/v2/organizations')
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-token')
    expect(calls[1].json).toEqual({ name: 'Acme Corp' })

    // Deal creation
    expect(calls[2].method).toBe('POST')
    expect(calls[2].url).toBe('https://api.pipedrive.com/v2/deals')
    expect(calls[2].headers.get('authorization')).toBe('Bearer test-token')
    expect(calls[2].json).toEqual({
      person_id: 12345,
      org_id: 67890,
      title: 'Enterprise Deal',
      value: 5000,
    })
  })

  it('uses company field over organization field for org name', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: [
          ...SOURCE_EXAMPLE.form_response.answers.filter((a) => a.field.id !== 'organization_field_id'),
          {
            type: 'text',
            text: 'Different Org',
            field: { id: 'organization_field_id', type: 'short_text' },
          },
        ],
      },
    } as unknown as TypeformWebhookPayload

    await handle(payload, baseConfig)
    expect(calls[1].json).toEqual({ name: 'Acme Corp' })
  })

  it('falls back to organization field when company is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter((a) => a.field.id !== 'company_field_id'),
      },
    } as unknown as TypeformWebhookPayload

    await handle(payload, baseConfig)
    expect(calls[1].json).toEqual({ name: 'Different Org' })
  })

  it('creates deal with minimal data when title and value are missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter(
          (a) => a.field.id !== 'dealname_field_id' && a.field.id !== 'price_field_id',
        ),
      },
    } as unknown as TypeformWebhookPayload

    await handle(payload, baseConfig)
    expect(calls[2].json).toEqual({ person_id: 12345, org_id: 67890 })
  })

  it('throws on missing first_name', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter((a) => a.field.id !== 'JwWggjAKtOkA'),
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: first_name')
  })

  it('throws on missing last_name', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter((a) => a.field.id !== 'last_name_field_id'),
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: last_name')
  })

  it('throws on missing email', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter((a) => a.field.id !== 'SMEUb7VJz92Q'),
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: email')
  })

  it('throws on missing company and organization', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      form_response: {
        ...SOURCE_EXAMPLE.form_response,
        answers: SOURCE_EXAMPLE.form_response.answers.filter(
          (a) => a.field.id !== 'company_field_id' && a.field.id !== 'organization_field_id',
        ),
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: company or organization for organization name')
  })

  it('throws on non-2xx response from create person', async () => {
    const fake = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, { ...baseConfig, fetch: fake.fetch }))
      .rejects.toThrow('Pipedrive create person failed: 401 Unauthorized at POST https://api.pipedrive.com/v2/persons')
  })

  it('throws on non-2xx response from create organization', async () => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons') return jsonResponse({ data: { id: 1 } }, 201)
      return jsonResponse({ error: 'forbidden' }, 403)
    })
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, { ...baseConfig, fetch: fake.fetch }))
      .rejects.toThrow('Pipedrive create organization failed: 403 Forbidden at POST https://api.pipedrive.com/v2/organizations')
  })

  it('throws on non-2xx response from create deal', async () => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons') return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url === 'https://api.pipedrive.com/v2/organizations') return jsonResponse({ data: { id: 2 } }, 201)
      return jsonResponse({ error: 'conflict' }, 409)
    })
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, { ...baseConfig, fetch: fake.fetch }))
      .rejects.toThrow('Pipedrive create deal failed: 409 Conflict at POST https://api.pipedrive.com/v2/deals')
  })

  it('throws when pipedriveApiToken is missing', async () => {
    await expect(handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, { fetch }))
      .rejects.toThrow('Missing required config: pipedriveApiToken')
  })

  it('throws on unsupported event type', async () => {
    const payload = { ...SOURCE_EXAMPLE, event_type: 'other' } as unknown as TypeformWebhookPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Unsupported event type: other')
  })

  it('retries on 429 and succeeds on second attempt', async () => {
    let attempt = 0
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        attempt++
        if (attempt === 1) return jsonResponse({ error: 'rate limited' }, 429)
        return jsonResponse({ data: { id: 12345 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/organizations') return jsonResponse({ data: { id: 67890 } }, 201)
      if (req.url === 'https://api.pipedrive.com/v2/deals') return jsonResponse({ data: { id: 54321 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch: fake.fetch, maxRetries: 3, baseRetryDelayMs: 10 }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    await vi.runAllTimersAsync()
    const result = await promise
    vi.useRealTimers()

    expect(result.personId).toBe(12345)
    expect(fake.calls.filter((c) => c.url === 'https://api.pipedrive.com/v2/persons')).toHaveLength(2)
  })

  it('retries up to maxRetries then throws on persistent 429', async () => {
    const fake = fakeFetch(() => jsonResponse({ error: 'rate limited' }, 429))
    const config = { ...baseConfig, fetch: fake.fetch, maxRetries: 2, baseRetryDelayMs: 10 }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    await vi.runAllTimersAsync()
    await expect(promise).rejects.toThrow('Pipedrive create person failed: 429 Too Many Requests at POST https://api.pipedrive.com/v2/persons')
    vi.useRealTimers()

    expect(fake.calls.filter((c) => c.url === 'https://api.pipedrive.com/v2/persons')).toHaveLength(3)
  })

  it('parses Retry-After header as seconds', async () => {
    let attempt = 0
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        attempt++
        if (attempt === 1) {
          const res = jsonResponse({ error: 'rate limited' }, 429)
          res.headers.set('retry-after', '1')
          return res
        }
        return jsonResponse({ data: { id: 12345 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/organizations') return jsonResponse({ data: { id: 67890 } }, 201)
      if (req.url === 'https://api.pipedrive.com/v2/deals') return jsonResponse({ data: { id: 54321 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch: fake.fetch, maxRetries: 3, baseRetryDelayMs: 1000 }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    await vi.runAllTimersAsync()
    await promise
    vi.useRealTimers()

    expect(fake.calls.filter((c) => c.url === 'https://api.pipedrive.com/v2/persons')).toHaveLength(2)
  })

  it('parses Retry-After header as HTTP date', async () => {
    let attempt = 0
    const futureDate = new Date(Date.now() + 500).toUTCString()
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        attempt++
        if (attempt === 1) {
          const res = jsonResponse({ error: 'rate limited' }, 429)
          res.headers.set('retry-after', futureDate)
          return res
        }
        return jsonResponse({ data: { id: 12345 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/organizations') return jsonResponse({ data: { id: 67890 } }, 201)
      if (req.url === 'https://api.pipedrive.com/v2/deals') return jsonResponse({ data: { id: 54321 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch: fake.fetch, maxRetries: 3, baseRetryDelayMs: 1000 }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    await vi.runAllTimersAsync()
    await promise
    vi.useRealTimers()

    expect(fake.calls.filter((c) => c.url === 'https://api.pipedrive.com/v2/persons')).toHaveLength(2)
  })
})

